            }
            is CloseTabsResult.TabsNotClosed -> {
                buf.putInt(2)
                FfiConverterSequenceString.write(value.`urls`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





