                buf.putInt(7)
                Unit
            }
            is FxaException.Panic -> {
                buf.putInt(8)
                Unit
            }
            is FxaException.Other -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Fxa event
 *
 * These are the events that consumers send to [crate::FxaStateMachine::process_event]
 */
sealed class FxaEvent {
    
    /**
     * Initialize the state machine.  This must be the first event sent.
     */
    data class Initialize(
        val `deviceConfig`: mozilla.appservices.fxaclient.DeviceConfig) : FxaEvent()
        
    {
        

        companion object
    }
    
    /**
     * Begin an oauth flow
     *
     * If successful, the state machine will transition the [FxaState::Authenticating].  The next
     * step is to navigate the user to the `oauth_url` and let them sign and authorize the client.
     *
     * This event is valid for the `Disconnected`, `AuthIssues`, and `Authenticating` states.  If
     * the state machine is in the `Authenticating` state, then this will forget the current OAuth
     * flow and start a new one.
     */
    data class BeginOAuthFlow(
        val `service`: kotlin.String, 
        val `scopes`: List<kotlin.String>, 
        val `entrypoint`: kotlin.String) : FxaEvent()
        
    {
        

        companion object
    }
    
    /**
     * Begin an oauth flow using a URL from a pairing code
     *
     * If successful, the state machine will transition the [FxaState::Authenticating].  The next
     * step is to navigate the user to the `oauth_url` and let them sign and authorize the client.
     *
     * This event is valid for the `Disconnected`, `AuthIssues`, and `Authenticating` states.  If
     * the state machine is in the `Authenticating` state, then this will forget the current OAuth
     * flow and start a new one.
     */
    data class BeginPairingFlow(
        val `pairingUrl`: kotlin.String, 
        val `service`: kotlin.String, 
        val `scopes`: List<kotlin.String>, 
        val `entrypoint`: kotlin.String) : FxaEvent()
        
    {
        

        companion object
    }
    
    /**
     * Complete an OAuth flow.
     *
     * Send this event after the user has navigated through the OAuth flow and has reached the
     * redirect URI.  Extract `code` and `state` from the query parameters or web channel.  If
     * successful the state machine will transition to [FxaState::Connected].
     *
     * This event is valid for the `Authenticating` state.
     */
    data class CompleteOAuthFlow(
        val `code`: kotlin.String, 
        val `state`: kotlin.String) : FxaEvent()
        
    {
        

        companion object
    }
    
    /**
     * Cancel an OAuth flow.
     *
     * Use this to cancel an in-progress OAuth, returning to [FxaState::Disconnected] so the
     * process can begin again.
     *
     * This event is valid for the `Authenticating` state.
     */
    object CancelOAuthFlow : FxaEvent()
    
    
    /**
     * Check the authorization status for a connected account.
     *
     * Send this when issues are detected with the auth tokens for a connected account.  It will
     * double check for authentication issues with the account.  If it detects them, the state
     * machine will transition to [FxaState::AuthIssues].  From there you can start an OAuth flow
     * again to re-connect the user.
     *
     * This event is valid for the `Connected` state.
     */
    object CheckAuthorizationStatus : FxaEvent()
    
    
    /**
     * An `fxaccounts:change_password` WebChannel message arrived on the device that just changed
     * its password. `json_payload` is the `data` object of that message and contains the new
     * session token. The state machine swaps the session token for a new refresh token and
     * re-initialises the device record.
     *
     * This event is valid for the `Connected` and `AuthIssues` states. In `Authenticating` it
     * is a no-op so the in-progress OAuth flow is not disrupted.
     */
    data class WebChannelPasswordChange(
        val `jsonPayload`: kotlin.String) : FxaEvent()
        
    {
        

        companion object
    }
    
    /**
     * Disconnect the user
     *
     * Send this when the user is asking to be logged out.  The state machine will transition to
     * [FxaState::Disconnected].
     *
     * This event is valid for the `Connected` state.
     */
    object Disconnect : FxaEvent()
    
    
    /**
     * Force a call to [FirefoxAccount::get_profile]
     *
     * This is used for testing the auth/network retry code, since it hits the network and
     * requires and auth token.
     *
     * This event is valid for the `Connected` state.
     */
    object CallGetProfile : FxaEvent()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFxaEvent : FfiConverterRustBuffer<FxaEvent>{
    override fun read(buf: ByteBuffer): FxaEvent {
        return when(buf.getInt()) {
            1 -> FxaEvent.Initialize(
                FfiConverterTypeDeviceConfig.read(buf),
                )
            2 -> FxaEvent.BeginOAuthFlow(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> FxaEvent.BeginPairingFlow(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> FxaEvent.CompleteOAuthFlow(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> FxaEvent.CancelOAuthFlow
            6 -> FxaEvent.CheckAuthorizationStatus
            7 -> FxaEvent.WebChannelPasswordChange(
                FfiConverterString.read(buf),
                )
            8 -> FxaEvent.Disconnect
            9 -> FxaEvent.CallGetProfile
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FxaEvent): ULong = when(value) {
        is FxaEvent.Initialize -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDeviceConfig.allocationSize(value.`deviceConfig`)
            )
        }
        is FxaEvent.BeginOAuthFlow -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`service`)
                + FfiConverterSequenceString.allocationSize(value.`scopes`)
                + FfiConverterString.allocationSize(value.`entrypoint`)
            )
        }
        is FxaEvent.BeginPairingFlow -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`pairingUrl`)
                + FfiConverterString.allocationSize(value.`service`)
                + FfiConverterSequenceString.allocationSize(value.`scopes`)
                + FfiConverterString.allocationSize(value.`entrypoint`)
            )
        }
        is FxaEvent.CompleteOAuthFlow -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`state`)
            )
        }
        is FxaEvent.CancelOAuthFlow -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FxaEvent.CheckAuthorizationStatus -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FxaEvent.WebChannelPasswordChange -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`jsonPayload`)
            )
        }
        is FxaEvent.Disconnect -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FxaEvent.CallGetProfile -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FxaEvent, buf: ByteBuffer) {
        when(value) {
            is FxaEvent.Initialize -> {
                buf.putInt(1)
                FfiConverterTypeDeviceConfig.write(value.`deviceConfig`, buf)
                Unit
            }
            is FxaEvent.BeginOAuthFlow -> {
                buf.putInt(2)
                FfiConverterString.write(value.`service`, buf)
                FfiConverterSequenceString.write(value.`scopes`, buf)
                FfiConverterString.write(value.`entrypoint`, buf)
                Unit
            }
            is FxaEvent.BeginPairingFlow -> {
                buf.putInt(3)
                FfiConverterString.write(value.`pairingUrl`, buf)
                FfiConverterString.write(value.`service`, buf)
                FfiConverterSequenceString.write(value.`scopes`, buf)
                FfiConverterString.write(value.`entrypoint`, buf)
                Unit
            }
            is FxaEvent.CompleteOAuthFlow -> {
                buf.putInt(4)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`state`, buf)
                Unit
            }
            is FxaEvent.CancelOAuthFlow -> {
                buf.putInt(5)
                Unit
            }
            is FxaEvent.CheckAuthorizationStatus -> {
                buf.putInt(6)
                Unit
            }
            is FxaEvent.WebChannelPasswordChange -> {
                buf.putInt(7)
                FfiConverterString.write(value.`jsonPayload`, buf)
                Unit
            }
            is FxaEvent.Disconnect -> {
                buf.putInt(8)
                Unit
            }
            is FxaEvent.CallGetProfile -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





