/**
 * Fxa state
 *
 * These are the states of [crate::FxaStateMachine] that consumers observe.
 */
sealed class FxaState {
    
    /**
     * The state machine needs to be initialized via [Event::Initialize].
     */
    object Uninitialized : FxaState()
    
    
    /**
     * User has not connected to FxA or has logged out
     */
    object Disconnected : FxaState()
    
    
    /**
     * User is currently performing an OAuth flow - our existing initial state
     * when we transition to this state will influence what this means exactly.
     */
    data class Authenticating(
        val `oauthUrl`: kotlin.String, 
        val `initialState`: mozilla.appservices.fxaclient.FxaRustAuthState) : FxaState()
        
    {
        

        companion object
    }
    
    /**
     * User is currently connected to FxA
     */
    object Connected : FxaState()
    
    
    /**
     * User was connected to FxA, but we observed issues with the auth tokens.
     * The user needs to reauthenticate before the account can be used.
     */
    object AuthIssues : FxaState()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFxaState : FfiConverterRustBuffer<FxaState>{
    override fun read(buf: ByteBuffer): FxaState {
        return when(buf.getInt()) {
            1 -> FxaState.Uninitialized
            2 -> FxaState.Disconnected
            3 -> FxaState.Authenticating(
                FfiConverterString.read(buf),
                FfiConverterTypeFxaRustAuthState.read(buf),
                )
            4 -> FxaState.Connected
            5 -> FxaState.AuthIssues
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FxaState): ULong = when(value) {
        is FxaState.Uninitialized -> {
