            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FxaState.Authenticating -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`oauthUrl`)
                + FfiConverterTypeFxaRustAuthState.allocationSize(value.`initialState`)
            )
        }
        is FxaState.Connected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FxaState.AuthIssues -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FxaState, buf: ByteBuffer) {
        when(value) {
            is FxaState.Uninitialized -> {
                buf.putInt(1)
                Unit
            }
            is FxaState.Disconnected -> {
                buf.putInt(2)
                Unit
            }
            is FxaState.Authenticating -> {
