                Unit
            }
            is FxaState.Connected -> {
                buf.putInt(4)
                Unit
            }
            is FxaState.AuthIssues -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





